#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        int n = nums.size();
        vector<long long> squares(n);
        for (int i = 0; i < n; ++i) {
            long long val = nums[i];
            squares[i] = val * val;
        }
        sort(squares.begin(), squares.end());

        long long total = 0;
        int l = 0, r = n - 1;
        bool add = true;

        while (l <= r) {
            if (add) {
                total += squares[r];
                r--;
            } else {
                total -= squares[l];
                l++;
            }
            add = !add;
        }

        return total;
    }
};
